def largest_divisor(n: int) -> int:
    """For a given number n, find the largest number that divides n evenly, smaller than n"""
    if n <= 1:
        return 0
    if n == 2:
        return 1
    if n % 2 == 0:
        return n // 2

    # Check odd factors from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    # If no factor found, n is prime, so the largest proper divisor is 1
    return 1
```

