        """Check if a number is prime efficiently."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check odd divisors up to sqrt(n)
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    max_prime = None

    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0 

    # Calculate sum of digits
    digit_sum = 0
    temp = max_prime
    while temp > 0:
        digit_sum += temp % 10
        temp //= 10

    return digit_sum
