def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    '''

    # Step 1: Check if any whitespace character exists in the string
    if any(c.isspace() for c in txt):
        return txt.split()

    # Step 2: Check if a comma exists in the string
    if ',' in txt:
        return txt.split(',')

    # Step 3: Count lowercase letters with odd alphabetical index (0-based)
    count = 0
    for char in txt:
        # Check if the character is a lowercase letter
        if 'a' <= char <= 'z':
            # Calculate 0-based index: ord('a') is 97
            index = ord(char) - ord('a')
            # Check if the index is odd
            if index % 2 != 0:
                count += 1

    return count
```

