    # Define the ordered list of planets
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Validate inputs: return empty tuple if either planet name is invalid
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Get indices of both planets
    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)

    # If they are the same, there are no planets between them
    if idx1 == idx2:
        return ()

    # Determine the range (exclusive of the end planet)
    # Start is the index after the closer planet
    start = min(idx1, idx2) + 1
    # End is the index of the farther planet (slicing excludes this index)
    end = max(idx1, idx2)

    # Extract the intermediate planets and return as a tuple
    return tuple(planets[start:end])
