def split_words(txt):
    # Priority 1: Check for whitespace
    if ' ' in txt:
        return txt.split()

    # Priority 2: Check for commas
    elif ',' in txt:
        return txt.split(',')

    # Priority 3: Count odd-order lowercase letters
    else:
        count = 0
        for char in txt:
            # Check if character is a lowercase letter
            if 'a' <= char <= 'z':
                # Calculate zero-based index in alphabet
                index = ord(char) - ord('a')
                # Check if index is odd
                if index % 2 != 0:
                    count += 1
        return count
