def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 0:
                # Logic to handle 3 or more spaces
                if space_count >= 3:
                    result.append('-')
                else:
                    # Logic for 1 or 2 spaces
                    result.append('_')
                space_count = 0
            result.append(char)

    # Handle trailing spaces
    if space_count > 0:
        if space_count >= 3:
            result.append('-')
        else:
            result.append('_')

    return "".join(result)
