    for i, val in enumerate(lst):
        if i % 3 == 0:
            # Rule 1: Index is a multiple of 3 -> Square
            total_sum += val ** 2
        elif i % 4 == 0:
            # Rule 2: Index is a multiple of 4 AND NOT a multiple of 3 -> Cube
            total_sum += val ** 3
        else:
            # Rule 3: Otherwise -> Keep original
            total_sum += val

    return total_sum
