def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Dictionary to store the frequency of each character
    counts = {}

    # Variable to store the maximum frequency found so far
    max_count = 0

    # Iterate through each character in the input string
    for char in test:
        # Increment the count for the current character
        if char in counts:
            counts[char] += 1
        else:
            # Initialize count to 1 if the character is new
            counts[char] = 1

            # Update max_count if the current character has a higher count
            if counts[char] > max_count:
                max_count = counts[char]

    # Return the dictionary of counts
    return counts
