def largest_smallest_integers(lst):
    """
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.
    """
    # 1. Handle empty list case
    if not lst:
        return (None, None)

    # 2. Find the smallest positive integer
    min_positive = float('inf')
    for num in lst:
        if num > 0:
            if num < min_positive:
                min_positive = num

    # 3. Find the largest negative integer
    max_negative = float('-inf')
    for num in lst:
        if num < 0:
            if num > max_negative:
                max_negative = num

    # 4. Determine if any negative or positive numbers exist
    has_negative = min_positive is not None
    has_positive = max_negative is not None

    # 5. Return the appropriate tuple
    if has_negative and has_positive:
        return (max_negative, min_positive)
    elif has_negative:
        return (None, min_positive)
    else:
        return (max_negative, None)
