    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False

        # Check odd divisors up to sqrt(n)
        limit = int(math.isqrt(n))
        # Start checking from 3, stepping by 2 to skip even numbers
        for i in range(3, limit, 2):
            if n % i == 0:
                return False
        return True

    max_prime = None

    for num in lst:
        if num < 2:
            continue

