            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0

    # Calculate sum of digits
    digit_sum = 0
    temp = max_prime
    while temp > 0:
        digit_sum += temp % 10
        temp //= 10

    return digit_sum
