def count_nums(arr):
    count = 0

    for n in arr:
        s = str(n)
        digit_sum = 0

        if s.startswith('-'):
            # Handle negative numbers: first digit is negative, rest are positive
            if len(s) > 1:
                digit_sum -= int(s[1])
                for char in s[2:]:
                    digit_sum += int(char)
            else:
                # Edge case for "-0" or similar, sum is 0
                digit_sum = 0
        else:
            # Handle positive numbers and zero
            for char in s:
                digit_sum += int(char)

        if digit_sum > 0:
            count += 1

    return count
