def sort_array(arr):
    """
    Sorts an array of integers based on the number of ones in their binary representation.
    For numbers with the same number of ones, sorts by decimal value.
    """
    def get_sort_key(n):
        # Handle negative numbers by treating their bit count as 0 to sort by value
        if n < 0:
            return (0, n)

        # Count the number of '1's in the binary representation
        # Using bin() string conversion to count ones
        binary_rep = bin(n)
        ones_count = binary_rep.count('1')

        return (ones_count, n)

    # Sort the array using the custom key
    # Note: The sort is stable, so equal keys maintain relative order
    return sorted(arr, key=get_sort_key)
```

