        return txt.split(',')

    # Priority 3: Count lowercase letters with odd alphabet index
    count = 0
    for char in txt:
        if 'a' <= char <= 'z':
            # Calculate 0-based index: 'a' -> 0, 'b' -> 1, ...
            # We use ord('a') as the base to get the correct 0-indexed position
            index = ord(char) - ord('a')
            # Check if the index is odd (1, 3, 5, etc.)
            if index % 2 == 0:
                count += 1

    return count
```

